using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace IanGame.Editor {
public static class RoomVisualSetup {
 const string Data="Assets/_Game/Data/RoomVisual/";
 static RoomSceneCatalog Catalog=>AssetDatabase.LoadAssetAtPath<RoomSceneCatalog>("Assets/_Game/Data/SceneArchitecture/RoomScenes.asset");
 static Dictionary<string,Sprite> Art=>AssetDatabase.LoadAllAssetsAtPath("Assets/_Game/Art/VisualRebuild/Architecture.png").OfType<Sprite>().ToDictionary(s=>s.name);
 static Material Material=>AssetDatabase.LoadAssetAtPath<Material>("Assets/_Game/Art/VisualRebuild/WorldAlphaCut.mat");
 [MenuItem("Ian/Room Visual/Audit existing interiors")]
 public static void Audit(){if(Application.isPlaying)throw new Exception("Stop Play first");Directory.CreateDirectory("Docs/RoomVisual");var lines=new List<string>();foreach(var r in Catalog.rooms){var z=Catalog.rules.Zone(r.roomId);if(z.outdoor)continue;EditorSceneManager.OpenScene("Assets/_Game/Scenes/Rooms/"+r.sceneName+".unity");var w=UnityEngine.Object.FindAnyObjectByType<LifeWorldController>();lines.Add($"{r.sceneName}: floor={z.size} ortho={w.follow.target.orthographicSize} offset={w.Room.cameraOffset} bounds={z.size} canvas={w.hud.GetComponent<WorldMobileHUD>().scaler.referenceResolution}");foreach(var o in w.objects.Where(o=>o.kind==WorldInteractionKind.Shower||o.kind==WorldInteractionKind.Door)){var sr=o.visual;lines.Add($" {o.id}: feet={o.Point-z.origin} PPU={sr?.sprite?.pixelsPerUnit} bounds={sr?.bounds} alpha={sr?.color.a} scale={sr?.transform.lossyScale} action={o.GetComponent<WorldLifeAction>()?.mode}");}}File.WriteAllLines("Docs/RoomVisual/BEFORE_AUDIT.txt",lines);}
 static Sprite Crop(string name,Sprite src,Rect normalized,float ppuMultiplier=1){string path=Data+name+".asset";var result=AssetDatabase.LoadAssetAtPath<Sprite>(path);if(result!=null)return result;var r=src.rect;var rect=new Rect(r.x+normalized.x*r.width,r.y+normalized.y*r.height,normalized.width*r.width,normalized.height*r.height);result=Sprite.Create(src.texture,rect,new Vector2(.5f,.5f),src.pixelsPerUnit*ppuMultiplier,0,SpriteMeshType.FullRect);result.name=name;AssetDatabase.CreateAsset(result,path);return result;}
 static void Center(SpriteRenderer sr,Vector2 p,Vector2 size){sr.drawMode=SpriteDrawMode.Tiled;sr.size=size;sr.transform.position=p-new Vector2((.5f-sr.sprite.pivot.x/sr.sprite.rect.width)*size.x,(.5f-sr.sprite.pivot.y/sr.sprite.rect.height)*size.y);}
 static SpriteRenderer Surface(Transform root,string name,Sprite image,Vector2 p,Vector2 size,int order){var matches=root.Cast<Transform>().Where(t=>t.name==name).ToArray();var t=matches.FirstOrDefault();foreach(var duplicate in matches.Skip(1))UnityEngine.Object.DestroyImmediate(duplicate.gameObject);if(t==null){t=new GameObject(name,typeof(SpriteRenderer)).transform;t.SetParent(root,false);}var sr=t.GetComponent<SpriteRenderer>();sr.sprite=image;sr.sharedMaterial=Material;sr.sortingOrder=order;Center(sr,p,size);return sr;}
 [MenuItem("Ian/Room Visual/Apply room framing and shower alignment")]
 public static void Apply(){if(Application.isPlaying)throw new Exception("Stop Play first");Directory.CreateDirectory(Data);var art=Art;var plaster=Crop("HousePlaster",art["IvoryWall"],new Rect(.15f,.25f,.68f,.55f));var porcelain=Crop("FamilyPorcelain",art["KitchenFloor"],new Rect(0,0,1,1));var sill=Crop("DoorThresholdWood",art["OakFloor"],new Rect(.05f,.1f,.85f,.65f));var plain=Crop("QuietPlaster",art["IvoryWall"],new Rect(.01f,.28f,.04f,.05f));var catalog=Catalog;var bath=catalog.rules.Zone("family-bathroom");bath.size=new Vector2(5.2f,3.8f);bath.walkableTop=1.9f;bath.spawn=new Vector2(0,-.95f);foreach(var p in catalog.portals.Where(p=>p.destinationRoom=="family-bathroom"))p.arrival=new Vector2(0,-.95f);
  foreach(var room in catalog.rooms){var z=catalog.rules.Zone(room.roomId);if(z.outdoor)continue;var scene=EditorSceneManager.OpenScene("Assets/_Game/Scenes/Rooms/"+room.sceneName+".unity");var w=UnityEngine.Object.FindAnyObjectByType<LifeWorldController>();var id=w.Room;var origin=z.origin;
   id.interior=new IndoorCameraSettings{enabled=true,bounds=new Rect(-z.size.x/2,-z.size.y/2-.85f,z.size.x,z.size.y+2.15f),halfHeight=room.roomId=="family-bathroom"?3.2f:room.roomId.StartsWith("family-")?4.5f:Mathf.Max(z.cameraSize,(z.size.y+1.8f)/2),offset=new Vector2(0,.4f),minScale=3,maxScale=8};
   w.follow.target.backgroundColor=new Color(.61f,.58f,.52f);w.follow.target.orthographicSize=id.interior.QuantizedSize(720);
   var surround=w.GetComponent<InteriorSurround>()??w.gameObject.AddComponent<InteriorSurround>();surround.cameraRig=w.follow;surround.plaster=Surface(w.transform,"House construction outside camera cutaway",plaster,origin,new Vector2(50,50),-32000);surround.plaster.color=new Color(.80f,.79f,.75f,.12f);
   if(room.roomId=="bathroom"){
    // Legacy export retained these disabled renderers after removing its old home presentation owner.
    foreach(var sr in w.GetComponentsInChildren<SpriteRenderer>(true)){
     if(sr.name=="Walkable floor"){sr.transform.localScale=Vector3.one;sr.sprite=art["JadeFloor"];sr.sharedMaterial=Material;sr.sortingOrder=-5000;Center(sr,origin,z.size);sr.enabled=true;}
     if(sr.name=="Back wall"){sr.sprite=art["JadeWall"];sr.sharedMaterial=Material;sr.sortingOrder=-4000;Center(sr,origin+Vector2.up*(z.size.y/2+.5f),new Vector2(z.size.x,1));sr.enabled=true;}
     if(sr.name=="Left wall"||sr.name=="Right wall"){sr.sprite=art["VerticalWall"];sr.sharedMaterial=Material;Center(sr,origin+Vector2.right*(sr.name=="Left wall"?-z.size.x/2:z.size.x/2),new Vector2(.22f,z.size.y));sr.drawMode=SpriteDrawMode.Sliced;sr.sortingOrder=-3500;sr.enabled=true;}
    }
   }
   if(room.family){var root=w.transform.Cast<Transform>().First(t=>t.name.EndsWith(" / "+room.roomId));var floor=root.Find("Room owned floor").GetComponent<SpriteRenderer>();if(room.roomId=="family-bathroom")floor.sprite=porcelain;Center(floor,origin,z.size);foreach(var window in root.GetComponentsInChildren<SpriteRenderer>().Where(sr=>sr.name=="Bedroom daylight window"||sr.name=="Kitchen daylight window")){window.transform.localScale*=.9f/window.bounds.size.y;var center=new Vector3(window.bounds.center.x,origin.y+z.size.y/2+.48f,0);window.transform.position+=center-window.bounds.center;}var rear=root.Find("Room owned rear wallpaper").GetComponent<SpriteRenderer>();rear.sprite=room.roomId=="family-bathroom"?plain:plaster;Center(rear,origin+new Vector2(0,z.size.y/2+.48f),new Vector2(z.size.x,1f));Surface(root,"Continuous wall skirting",art["CutawayWall"],origin+new Vector2(0,z.size.y/2),new Vector2(z.size.x,.12f),-3500);Surface(root,"Single wall cap",art["CutawayWall"],origin+new Vector2(0,z.size.y/2+.96f),new Vector2(z.size.x,.12f),-3500);
    if(room.roomId=="family-bathroom"){foreach(var c in root.GetComponentsInChildren<BoxCollider2D>()){if(c.name.StartsWith("South wall"))c.transform.position=new Vector2(c.transform.position.x,origin.y-z.size.y/2);if(c.name=="West wall"||c.name=="East wall"){c.size=new Vector2(c.size.x,z.size.y);c.transform.position=new Vector2(c.transform.position.x,origin.y);}}
     foreach(var sr in root.GetComponentsInChildren<SpriteRenderer>()){if(sr.name.EndsWith(" visible")){Center(sr,new Vector2(sr.transform.position.x,origin.y+.1f),new Vector2(.22f,z.size.y+.2f));sr.drawMode=SpriteDrawMode.Sliced;}if(sr.name.Contains(" cutaway")){var c=root.GetComponentsInChildren<BoxCollider2D>().First(c=>c.name==sr.name.Replace(" cutaway",""));Center(sr,c.transform.position,new Vector2(c.size.x,.3f));}}
     foreach(var o in w.objects){if(o.kind==WorldInteractionKind.Door)o.transform.position=origin+new Vector2(0,-z.size.y/2)-(Vector2)o.GetComponent<WorldDoor>().threshold;if(o.id=="family-basin")o.transform.position=origin+new Vector2(-1.65f,.3f);if(o.id=="family-toilet")o.transform.position=origin+new Vector2(-.1f,.3f);if(o.id=="family-shower")o.transform.position=origin+new Vector2(1.5f,-.15f);if(o.visual!=null&&o.kind!=WorldInteractionKind.Door)o.visual.sortingOrder=1000-Mathf.RoundToInt(o.transform.position.y*100);}
     foreach(var n in catalog.rules.npcs)foreach(var e in n.schedule.Where(e=>e.zone==room.roomId)){var target=w.objects.FirstOrDefault(o=>o.id==e.objectId);if(target!=null)e.position=target.Point-origin;}
    }
   }
   foreach(var p in catalog.portals.Where(p=>p.destinationRoom==room.roomId)){var entry=w.GetComponentsInChildren<RoomEntryPoint>().FirstOrDefault(e=>e.entryId==p.destinationEntryId);if(entry!=null)entry.transform.position=origin+p.arrival;}
   foreach(var o in w.objects.Where(o=>o.kind==WorldInteractionKind.Door)){var d=o.GetComponent<WorldDoor>();if(d==null)continue;if(d.apertureShadow!=null){d.apertureShadow.sprite=plain;d.apertureShadow.color=new Color(.73f,.68f,.57f);d.apertureShadow.transform.position=d.Plane+Vector2.up*.7f;d.apertureShadow.transform.localScale=new Vector3(1.05f/plain.bounds.size.x,1.5f/plain.bounds.size.y,1);}Surface(w.transform,"Interior threshold / "+o.id,room.roomId=="family-bathroom"?porcelain:room.roomId.EndsWith("bathroom")?art["JadeFloor"]:sill,d.Plane,new Vector2(1.3f,1.0f),-4800);}
   foreach(var o in w.objects.Where(o=>o.kind==WorldInteractionKind.Shower))SetupShower(o,porcelain);
   EditorUtility.SetDirty(id);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
  }
  // The other side of the bathroom door shares the updated entry metadata.
  var living=EditorSceneManager.OpenScene("Assets/_Game/Scenes/Rooms/FamilyHome_LivingRoom.unity");var owner=UnityEngine.Object.FindAnyObjectByType<LifeWorldController>();foreach(var o in owner.objects.Where(o=>o.targetZone=="family-bathroom"))o.arrival=new Vector2(0,-.95f);EditorSceneManager.MarkSceneDirty(living);EditorSceneManager.SaveScene(living);EditorUtility.SetDirty(catalog);EditorUtility.SetDirty(catalog.rules);AssetDatabase.SaveAssets();File.WriteAllText("Docs/RoomVisual/ROOMS_APPLIED.txt",string.Join("\n",catalog.rooms.Where(r=>!catalog.rules.Zone(r.roomId).outdoor).Select(r=>r.sceneName)));EditorSceneManager.OpenScene("Assets/_Game/Scenes/Rooms/FamilyHome_Bathroom.unity");
 }
 static void SetupShower(WorldInteractable o,Sprite tile){var a=o.GetComponent<WorldLifeAction>()??o.gameObject.AddComponent<WorldLifeAction>();a.mode=LifeActionVisual.Shower;a.facing=Vector2.down;var booth=o.GetComponent<ShowerBoothVisual>()??o.gameObject.AddComponent<ShowerBoothVisual>();booth.source=o.visual;booth.ceramic=tile;booth.barrier=o.GetComponent<BoxCollider2D>();a.booth=booth;float factor=2.1f/o.visual.bounds.size.y;o.visual.transform.localScale*=factor;
  Transform Point(string name,Vector2 local){var t=o.transform.Find(name);if(t==null){t=new GameObject(name).transform;t.SetParent(o.transform,false);}t.localPosition=local;return t;}
  a.approach=Point("ShowerApproachPoint",new Vector2(0,-.75f));a.anchor=Point("ShowerInsidePoint",new Vector2(0,.25f));a.standUp=Point("ShowerExitPoint",new Vector2(0,-.75f));o.UsePoint=new Vector2(0,-.75f);
  var slot=o.GetComponent<WorldActivitySlot>()??o.gameObject.AddComponent<WorldActivitySlot>();slot.useSeatAnchors=true;slot.seated=false;slot.seatAnchor=a.anchor;slot.approachAnchor=a.approach;slot.standUpAnchor=a.standUp;slot.facing=Vector2.down;slot.activityMotion=ActorMotion.Shower;a.seat=slot;if(booth.barrier!=null){booth.barrier.size=new Vector2(1.35f,.16f);booth.barrier.offset=new Vector2(0,.08f);}
 }
}
}
